INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'None published', 'Implementation date, threshold, and technical format');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'No format has been published', NULL, NULL, 'Qatar''s General Tax Authority has not published an e-invoicing schema, XML/UBL standard, or technical specification of any kind. The GTA''s own Dhareeba portal was checked directly and contains no e-invoicing content. Some industry commentary speculates Qatar might eventually adopt a Saudi ZATCA-style clearance model or a UAE-style Peppol network, given regional precedent -- but this is speculation about a still-undrafted regulation, not a confirmed technical choice, and this page does not treat it as fact.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s covered today', '[["B2B", "Not defined -- no mandate exists"], ["B2G", "Not defined -- no mandate exists"], ["B2C", "Not defined -- no mandate exists"], ["VAT regime", "Not yet implemented, despite a 2016 GCC Unified VAT Agreement commitment"]]', 'Every row in this table says "not defined" or "not yet implemented" for the same reason: Qatar''s e-invoicing law exists only as an unenacted draft.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What has to happen before this becomes real', '[["Step 1 (done)", "Council of Ministers approves the draft law and executive regulations -- 6 May 2026"], ["Step 2 (pending)", "Shura Council review -- no date reported"], ["Step 3 (pending)", "Submission to the Amir for enactment"], ["Step 4 (pending)", "Publication in the Official Gazette"]]', 'This tracker will add a real "on tracker" milestone the moment any of the pending steps is independently confirmed.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ No penalty schedule exists — because no mandate exists', NULL, NULL, 'There is nothing to penalize: Qatar has not enacted an e-invoicing requirement of any kind, so no fine or sanction schedule attaches to how (or whether) you issue invoices electronically.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 Unconfirmed industry timelines — deliberately not repeated here', NULL, NULL, 'Some industry write-ups (e.g. Wafeq) name specific dates such as "October 2026 notifications" or "January 2027 enforcement," but present these explicitly as analyst speculation, not figures published by Qatar''s government. Every official-adjacent source checked (EY, KPMG, PwC, Thomson Reuters) states plainly that no implementation timetable has been released. This page does not repeat the speculative dates as fact.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🌍 Context: the rest of the Gulf is moving faster', NULL, NULL, 'Saudi Arabia''s Fatoora system is live and mature; the UAE is phasing in a Peppol-based B2B mandate from July 2026; Oman has a live pilot. Qatar''s draft law, approved 6 May 2026, makes it the third GCC country to take a concrete legislative step -- but the only one still entirely at the draft stage, with Bahrain and Kuwait having taken no formal step at all.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'There is nothing to comply with today', 'No e-invoicing mandate is in force in Qatar. No registration, filing, or format change is required or even possible yet.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for the real signals of enactment', 'The draft law becomes real news at three specific points: a Shura Council vote, an Amiri Decree, or publication in the Official Gazette. Nothing short of one of these three has happened yet.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Expect a phased rollout by taxpayer size, if enacted', 'Every other GCC e-invoicing mandate built so far (Saudi Arabia, UAE, Oman) rolled out in waves by taxpayer size or revenue tier rather than all at once -- a reasonable expectation for Qatar too, though not yet confirmed.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Don''t plan around unofficial dates', 'Some industry commentary circulates specific 2026/2027 dates for Qatar. None of them is sourced to a Qatari government document -- treat them as speculation, not a compliance deadline, until this page says otherwise.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'QA';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Bookmark this page', 'This tracker will add a real milestone, update the stats, and publish a proper compliance timeline the moment Qatar''s draft law actually clears the Shura Council or is enacted.');
